using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterEdgeCaseTests
{
    private readonly ITestOutputHelper logger;

    public GeneratedFormatterEdgeCaseTests(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    public class CustomKey
    {
    }

    [Fact]
    public void UntrustedData_HashCollisionResistantComparer_RejectsUnknownType()
    {
        Assert.Throws<TypeAccessException>(() => global::MessagePack.MessagePackSecurity.UntrustedData.GetEqualityComparer<CustomKey>());
    }

    [Fact]
    public async Task DataContractOnReferencedType_IsHonoured()
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        CSharpParseOptions parseOptions = CSharpParseOptions.Default.WithLanguageVersion(LanguageVersion.Latest);

        string projectASource = """
            using System.Runtime.Serialization;

            namespace ProjectA
            {
                [DataContract]
                public class MyObject
                {
                    [DataMember(Name = "included")]
                    public int Included { get; set; }

                    public int Secret { get; set; }
                }
            }
            """;

        CSharpCompilation projectA = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(projectASource, parseOptions) },
            framework,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream stream = new();
        var emitResult = projectA.Emit(stream);
        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));
        MetadataReference projectARef = MetadataReference.CreateFromImage(stream.ToArray());

        string projectBSource = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                public partial class MyObjectFormatter : IMessagePackFormatter<ProjectA.MyObject> { }
            }
            """;

        ImmutableArray<MetadataReference> refs = framework.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).Add(projectARef);
        CSharpCompilation projectB = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(projectBSource, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new global::MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGenerators(projectB);
        GeneratorDriverRunResult result = driver.GetRunResult();
        foreach (Diagnostic d in result.Diagnostics)
        {
            this.logger.WriteLine(d.ToString());
        }

        string generated = string.Join("\n", result.GeneratedTrees.Select(t => t.ToString()));
        this.logger.WriteLine(generated);

        // The formatter must have been generated at all.
        Assert.Contains("Included", generated);

        // [DataContract] on the formatted type means only [DataMember] members are serialized.
        Assert.DoesNotContain("Secret", generated);
    }
}
